:root {
  --img-board-02-empty-tile: url("data:image/png;base64,");
  --img-board-02-filled-tile: url("data:image/png;base64,");
  --img-board-02-empty-scene: url("data:image/png;base64,");
  --img-board-02-filled-scene: url("data:image/png;base64,");
  --img-board-03-seat-empty-tile: url("data:image/png;base64,");
  --img-board-03-seat-taken-tile: url("data:image/png;base64,");
  --img-board-03-seat-empty-scene: url("data:image/png;base64,");
  --img-board-03-seat-taken-scene: url("data:image/png;base64,");
  --img-board-04-seat-empty-scene: url("data:image/png;base64,");
}

.board-img { display: block; width: 100%; height: 100%; background: center / contain no-repeat; }
.board-02-empty.board-scene .board-img { background-image: var(--img-board-02-empty-scene); }
.board-02-empty.board-160 .board-img, .board-02-empty.board-120 .board-img { background-image: var(--img-board-02-empty-tile); }
.board-02-filled.board-scene .board-img { background-image: var(--img-board-02-filled-scene); }
.board-02-filled.board-160 .board-img, .board-02-filled.board-120 .board-img { background-image: var(--img-board-02-filled-tile); }
.board-03-seat-empty.board-scene .board-img { background-image: var(--img-board-03-seat-empty-scene); }
.board-03-seat-empty.board-160 .board-img, .board-03-seat-empty.board-120 .board-img { background-image: var(--img-board-03-seat-empty-tile); }
.board-03-seat-taken.board-scene .board-img { background-image: var(--img-board-03-seat-taken-scene); }
.board-03-seat-taken.board-160 .board-img, .board-03-seat-taken.board-120 .board-img { background-image: var(--img-board-03-seat-taken-tile); }
.board-04-seat-empty.board-scene .board-img { background-image: var(--img-board-04-seat-empty-scene); }
body[data-figures="0"] .board { display: none; }
